Sample configuration using API key
{
"mcpServers": {
"freshdesk": {
"type": "http",
"url": "https://<subdomain>.freshdesk.com/mcp",
"headers": {
"Authorization": "<API-KEY>"
}
}
}
}

{
"mcpServers": {
